    max-width: 1600px;
    margin: 0 auto;
    min-height: 900px;
    position: relative;
    overflow: hidden;
  }

  .column {
    flex: 1;
    padding: 40px 45px;
    position: relative;
  }

  .column:nth-child(2) {
    border-left: 3px dashed #333;
    border-right: 3px dashed #333;
  }

  h2 {
    color: #0e8c66;
    font-size: 30px;
    margin: 0 0 15px 0;
    font-weight: 800;
